body.append('cover_letter', 'u');
body.append('privacy_consent', '1');
body.append('resume', document.querySelector('input[name="resume"]').files[0]);

fetch(url, {
    method: "POST",
    headers,
    body,
}).then(response =&gt; response.json());</code></pre></div>

